import{Game,HEROES,NAMES,STAGES}from'./engine.e0d35261d391.js';import{Renderer,hero}from'./render.e0d35261d391.js';import{installStick}from'./joystick.e0d35261d391.js';
const $=id=>document.getElementById(id),g=new Game(),r=new Renderer($('game')),input={},keys=new Set();let selected=0,best=0,stick,lastState='menu';try{best=Number(localStorage.getItem('jbJumpBest'))||0;}catch{}
function reset(){keys.clear();for(const k of Object.keys(input))delete input[k];stick?.reset();}
function start(){reset();g.start(selected);$('menu').hidden=true;$('modal').hidden=true;$('hud').hidden=false;$('touch').hidden=false;r.camera=0;$('app').focus();lastState='play';}
for(const [i,h]of HEROES.entries()){const b=document.createElement('button');b.className='hero';b.innerHTML=`<canvas width="100" height="120"></canvas><strong>${h.name}</strong><small>${h.skill}</small>`;b.setAttribute('aria-pressed',String(i===0));hero(b.querySelector('canvas').getContext('2d'),h,50,118,0);b.onclick=()=>{selected=i;[...$('heroes').children].forEach((e,j)=>e.setAttribute('aria-pressed',String(i===j)));};$('heroes').append(b);}
window.addEventListener('heroartready',()=>{[...$('heroes').querySelectorAll('canvas')].forEach((el,i)=>{const c=el.getContext('2d');c.clearRect(0,0,100,120);hero(c,HEROES[i],50,118,0);});});
$('start').onclick=start;
function pause(){if(g.state==='play'){g.state='pause';reset();}}
$('pause').onclick=()=>g.state==='pause'?resume():pause();function resume(){reset();g.state='play';$('modal').hidden=true;$('app').focus();lastState='play';}
$('continue').onclick=()=>{if(g.state==='pause')resume();else if(g.state==='clear'){g.next();reset();$('modal').hidden=true;lastState='play';}else start();};
$('home').onclick=()=>{reset();g.state='menu';$('menu').hidden=false;$('modal').hidden=true;$('hud').hidden=true;$('touch').hidden=true;};
$('copy').onclick=async()=>{const text=g.record();try{await navigator.clipboard.writeText(text);$('copy').textContent='복사 완료 ✓';}catch{$('record').value=text;$('record').hidden=false;$('record').focus();$('record').select();}};
function modal(){reset();$('modal').hidden=false;$('touch').hidden=true;$('copy').hidden=g.state==='pause';$('record').hidden=true;$('copy').textContent='기록 복사';const clear=g.state==='clear',win=g.state==='win',paused=g.state==='pause';$('modal-top').textContent=paused?'TAKE A BREAK':clear?'GOOOAL!':win?'ALL STAGES CLEAR':'TRY AGAIN';$('title').textContent=paused?'잠깐 쉬어가기':clear?`${g.level} 스테이지 클리어!`:win?'전주성에 도착했습니다!':'다시, 힘차게!';$('summary').textContent=paused?'준비되면 계속 달려보세요.':`${g.hero.name} · ${g.score.toLocaleString()}점 · 구슬 ${g.coins}개`;$('continue').textContent=paused?'계속 플레이':clear?(g.level===STAGES?'최종 기록 보기':'다음 스테이지 →'):'다시 도전';if(!paused&&g.score>best){best=g.score;try{localStorage.setItem('jbJumpBest',best);}catch{}}}
document.addEventListener('keydown',e=>{if(e.target.matches('textarea'))return;if(['ArrowLeft','ArrowRight','Space','KeyA'].includes(e.code)&&g.state==='play'){e.preventDefault();keys.add(e.code);if(e.code==='Space'&&!e.repeat)g.jump();if(e.code==='KeyA'&&!e.repeat)g.shoot();}if(e.code==='KeyP'||e.code==='Escape'){if(g.state==='pause')resume();else pause();}});document.addEventListener('keyup',e=>keys.delete(e.code));
for(const id of['shoot','jump']){const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();if(g.state!=='play')return;b.setPointerCapture(e.pointerId);if(id==='jump')g.jump();else input.shoot=true;});for(const ev of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{if(id==='shoot')input.shoot=false;});b.addEventListener('contextmenu',e=>e.preventDefault());}
stick=installStick($('stick-zone'),$('stick-base'),{enabled:()=>g.state==='play',onStart:()=>{},onMove:x=>input.axis=Math.abs(x)>.18?x:0});
window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('resize',reset);
$('full').onclick=async()=>{reset();try{if(document.fullscreenElement){await document.exitFullscreen();try{screen.orientation.unlock();}catch{}}else{await $('app').requestFullscreen();if(matchMedia('(pointer:coarse)').matches)try{await screen.orientation.lock('landscape');}catch{$('notice').textContent='휴대폰을 가로로 돌려주세요';}}}catch{if(self===top)$('app').classList.toggle('pseudo');else{pause();$('summary').textContent='게시판이 전체화면을 제한합니다. 아래 새 창 링크로 열어주세요.';}}};document.addEventListener('fullscreenchange',reset);
let previous=performance.now(),acc=0;function loop(now){acc+=Math.min(.1,(now-previous)/1000);previous=now;while(acc>=1/120){g.update(1/120,{...input,left:keys.has('ArrowLeft'),right:keys.has('ArrowRight'),shoot:input.shoot||keys.has('KeyA')});acc-=1/120;}r.draw(g,now/1000);if(g.state!==lastState){if(['clear','over','win','pause'].includes(g.state))modal();lastState=g.state;}if(g.state==='play'){$('touch').hidden=false;$('hud').innerHTML=`<span>${g.hero.name}　♥ ${g.p.hp}　목숨 ${g.lives}</span><span>${g.level}/${STAGES} ${NAMES[g.level-1]}</span><span>◈ ${g.coins}　${g.score.toLocaleString()}점　◷ ${Math.ceil(g.clock)}</span>`;$('notice').textContent=g.noticeTime>0?g.notice:'';}requestAnimationFrame(loop);}requestAnimationFrame(loop);
if(['127.0.0.1','localhost'].includes(location.hostname)&&location.search.includes('debug'))window.__jump={g,input,start,reset,r};
